<h1>سبد خرید</h1><?php if(!$items): ?><p class="empty">سبد خرید شما خالی است.</p><a class="outline" href="<?= e(url('shop')) ?>">فروشگاه</a><?php else: ?><section class="panel tablewrap"><table><thead><tr><th>محصول</th><th>قیمت واحد</th><th>تعداد</th></tr></thead><tbody><?php $total=0; foreach($items as $item): $price=(int)($item['sale_price']??$item['price']);$total+=$price*(int)$item['quantity']; ?><tr><td><?= e($item['title']) ?><small><?= e($item['attributes']) ?></small></td><td><?= fa(number_format($price)) ?> تومان</td><td><form method="post"><?= Namira\Security::field() ?><input type="hidden" name="action" value="cart"><input type="hidden" name="variant_id" value="<?= $item['id'] ?>"><input aria-label="تعداد" name="quantity" type="number" min="0" max="99" value="<?= $item['quantity'] ?>"><button class="outline">به‌روزرسانی</button></form></td></tr><?php endforeach ?></tbody></table><p>جمع کالاها: <?= fa(number_format($total)) ?> تومان</p><p>هزینه ارسال ثابت: <?= fa(number_format((int)Namira\Env::get('SHIPPING_TOMAN','50000'))) ?> تومان</p></section><section class="request"><h2>اطلاعات تسویه‌حساب</h2><?php if(Namira\Env::get('PAYMENT_DRIVER')!=='test'||Namira\Env::get('APP_ENV')==='production'): ?><p class="notice">درگاه بانکی هنوز متصل نیست؛ ثبت خرید تا فعال‌شدن اتصال واقعی غیرفعال است.</p><?php else: ?><p class="notice">محیط آزمایشی: این خرید هیچ انتقال وجهی انجام نمی‌دهد.</p><form method="post"><?= Namira\Security::field() ?><input type="hidden" name="action" value="checkout"><?php if(Namira\MemberSchema::ready($db)): ?><label>آدرس ذخیره‌شده؛ اختیاری<select name="address_id"><option value="">نشانی واردشده در همین فرم</option><?php foreach(Namira\Db::query($db,"SELECT id,title FROM account_addresses WHERE user_id=?",[$user["id"]])->fetchAll() as $saved): ?><option value="<?= (int)$saved["id"] ?>"><?= e($saved["title"]) ?></option><?php endforeach ?></select></label><?php endif ?><input type="hidden" name="checkout_key" value="<?= e($_SESSION['checkout_key']) ?>"><?php foreach(['customer'=>'نام گیرنده','phone'=>'موبایل','postal_code'=>'کدپستی ۱۰ رقمی','discount_code'=>'کد تخفیف (اختیاری)'] as $k=>$label): ?><label for="<?= $k ?>"><?= $label ?></label><input id="<?= $k ?>" name="<?= $k ?>" <?= $k!=='discount_code'?'required':'' ?>><?php endforeach ?><label for="address">استان، شهر و نشانی کامل</label><textarea name="address" id="address" required></textarea><button class="primary">ثبت سفارش آزمایشی</button></form><?php endif ?></section><?php endif ?>
